using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// Options with the default reflection-based resolver (resolves any type)
var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

// 1) GetTypeInfo<T>() — returns JsonTypeInfo<T> directly, no cast needed
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person> → Type = {personInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Alice", 42), personInfo);
Console.WriteLine($"  Serialized: {json}");

Person? roundTrip = JsonSerializer.Deserialize(json, personInfo);
Console.WriteLine($"  Deserialized: {roundTrip}");

// 2) TryGetTypeInfo<T>() — probe without throwing
//    With the default resolver, every type resolves, so Person succeeds:
if (options.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? info))
    Console.WriteLine($"\nTryGetTypeInfo<Person> → resolved ({info!.Type.Name})");
else
    Console.WriteLine("\nTryGetTypeInfo<Person> → not available");

// Now create options with a source-gen context that only knows about Person.
// Querying for a type the context doesn't handle (int[]) will return false.
var limited = new JsonSerializerOptions { TypeInfoResolver = PersonContext.Default };

if (limited.TryGetTypeInfo<int[]>(out JsonTypeInfo<int[]>? arrayInfo))
    Console.WriteLine($"TryGetTypeInfo<int[]>  → resolved ({arrayInfo!.Type.Name})");
else
    Console.WriteLine("TryGetTypeInfo<int[]>  → not available (expected)");

public record Person(string Name, int Age);

[JsonSerializable(typeof(Person))]
public partial class PersonContext : JsonSerializerContext;

